const hamburger=document.getElementById("hamburger"),navMenu=document.getElementById("navMenu");hamburger&&navMenu&&hamburger.addEventListener("click",()=>{navMenu.classList.toggle("active")}),document.querySelectorAll(".nav-menu a").forEach(e=>{e.addEventListener("click",()=>{navMenu&&navMenu.classList.remove("active")})});const scrollTop=document.getElementById("scrollTop");window.addEventListener("scroll",()=>{window.scrollY>300?scrollTop.classList.add("active"):scrollTop.classList.remove("active")}),scrollTop&&scrollTop.addEventListener("click",()=>{window.scrollTo({top:0,behavior:"smooth"})});const sections=document.querySelectorAll("section[id]");window.addEventListener("scroll",()=>{let e="";sections.forEach(t=>{const n=t.offsetTop;scrollY>=n-200&&(e=t.getAttribute("id"))}),document.querySelectorAll(".nav-menu a").forEach(t=>{t.classList.remove("active"),t.getAttribute("href")==="#"+e&&t.classList.add("active")})})